(function(){'use strict';var self=document.currentScript;var CSS=self.dataset.css;var JS=self.dataset.js;var pending=null;function load(){if(pending)return pending;pending=new Promise(function(resolve,reject){var link=document.createElement('link');link.rel='stylesheet';link.href=CSS;document.head.appendChild(link);var script=document.createElement('script');script.src=JS;script.onload=function(){resolve(window.Swal);};script.onerror=function(){pending=null;reject(new Error('failed to load SweetAlert2'));};document.head.appendChild(script);});return pending;}
window.Swal={fire:function(){var args=arguments;return load().then(function(Swal){return Swal.fire.apply(Swal,args);});},preload:load};['pointerdown','keydown'].forEach(function(evt){window.addEventListener(evt,function once(){window.removeEventListener(evt,once);load().catch(function(){});},{once:true,passive:true});});})();